Section Spec.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo size CA sb cnt mc : Z) (chunks : list Z) (j0 j1 j2 j3 : word).
  Let c := class_id size.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 48 <= bv_unsigned sp. Hypothesis SPA : bv_unsigned sp mod 16 = 0.
  Hypothesis Ha0 : a0 = wz AINST. Hypothesis Ha1 : a1 = wz CA. Hypothesis Ha2 : a2 = wz size. Hypothesis Ha3 : a3 = wz 8.
  Hypothesis SZ : 17 <= size <= kMaxSize.
  Hypothesis CAR : akobj CA 2592 /\ CA + 2592 <= aceil /\ CA mod 16 = 0.
  Hypothesis SBR : 0 <= sb /\ sb + kSpaceSize <= aceil.
  Hypothesis INST : rw_cells bsegs m (AINST + OI_SPACEBEG) [C8 (wz sb)].
  Hypothesis PC1 : rw_cells bsegs m (CA + PCLASS_SIZE * c) [C4 (wz cnt); C4 (wz mc)].
  Hypothesis PC2 : rw_cells bsegs m (CA + PCLASS_SIZE * c + 8) [C8 (wz (class_size c))].
  Hypothesis PC3 : u32arr bsegs m (CA + PCLASS_SIZE * c + 16) (wlist (rev chunks)).
  Hypothesis CNT : cnt = zlen chunks. Hypothesis HIT : 1 <= cnt <= 16.
  Hypothesis PC4 : stk bsegs m (CA + PCLASS_SIZE * c + 16 + 4 * cnt) (CA + PCLASS_SIZE * c + 80).
  Hypothesis CPS : Forall (fun cp => 0 <= cp < 2^32) chunks.
  Hypothesis STATS : rw_cells bsegs m (CA + CACHE_STATS) [C8 j0; C8 j1; C8 j2; C8 j3].

  Let CAE : 4096 <= CA /\ CA + 2592 <= aceil. Proof. exact (akobj_env _ _ (proj1 CAR) ltac:(clear; lia)). Qed.
Scheme kc__5 := Elimination for Corelib.Init.Logic.ex Sort Prop.   (* [comment removed for export] *)
  Theorem combined_hit_spec :
    evt bsegs (combined_hit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo (CA + PCLASS_SIZE * c) CA c sb cnt mc chunks)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
